class Solution {
public:
    int numberOfSets(int n, int k) {
        long long MOD = 1000000007;
        long long num = 1;
        long long den = 1;
        int N = n + k - 1;
        int K = 2 * k;
        for (int i = 0; i < K; ++i) {
            num = (num * (N - i)) % MOD;
            den = (den * (i + 1)) % MOD;
        }
        long long inv_den = 1;
        long long base = den;
        long long exp = MOD - 2;
        while (exp > 0) {
            if (exp % 2 == 1) inv_den = (inv_den * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2;
        }
        return (num * inv_den) % MOD;
    }
};
